function greedyCoins(coins, amount) {
  const sorted = coins.slice().sort((a, b) => b - a);
  const picked = [];
  let rem = amount;
  for (const c of sorted) {
    while (c <= rem) { rem -= c; picked.push(c); }
  }
  return rem === 0 ? picked : null;
}

