function maxItemsUnderBudget(prices, budget) {
  const sorted = prices.slice().sort((a, b) => a - b);
  let spent = 0, count = 0;
  for (const p of sorted) {
    if (spent + p > budget) break;
    spent += p;
    count += 1;
  }
  return count;
}

