function selectEarliestFinish(intervals) {
  const sorted = intervals.slice().sort((a, b) => a[1] - b[1]);
  const chosen = [];
  let lastEnd = -Infinity;
  for (const iv of sorted) {
    if (iv[0] >= lastEnd) { chosen.push(iv); lastEnd = iv[1]; }
  }
  return chosen;
}

