function minRoomsNeeded(intervals) {
  const starts = intervals.map(iv => iv[0]).sort((a, b) => a - b);
  const ends = intervals.map(iv => iv[1]).sort((a, b) => a - b);
  let i = 0, j = 0, cur = 0, best = 0;
  while (i < starts.length) {
    if (starts[i] < ends[j]) {
      cur += 1;
      if (cur > best) best = cur;
      i += 1;
    } else {
      cur -= 1;
      j += 1;
    }
  }
  return best;
}

function shortestPath(graph, source, target) {
  const nodes = Object.keys(graph);
  const dist = {}, prev = {}, done = {};
  for (const v of nodes) { dist[v] = Infinity; prev[v] = null; }
  dist[source] = 0;
  for (let k = 0; k < nodes.length; k++) {
    let u = null;
    for (const v of nodes) {
      if (!done[v] && dist[v] < Infinity && (u === null || dist[v] < dist[u])) u = v;
    }
    if (u === null) break;
    done[u] = true;
    for (const edge of graph[u]) {
      const w = edge[0], cost = edge[1];
      if (dist[u] + cost < dist[w]) { dist[w] = dist[u] + cost; prev[w] = u; }
    }
  }
  if (dist[target] === Infinity) return [];
  const path = [];
  let at = target;
  while (at !== null) { path.push(at); at = prev[at]; }
  return path.reverse();
}

